type OrderPort interface{ Place(ctx context.Context, o Order) (Receipt, error) }

type LegacyAdapter struct{ c *http.Client; base string }

func (a *LegacyAdapter) Place(ctx context.Context, o Order) (Receipt, error) {
    body, err := json.Marshal(toLegacy(o))         // explicit translation
    if err != nil { return Receipt{}, fmt.Errorf("acl: encode: %w", err) }
    resp, err := a.post(ctx, body)                 // transport + timeout inside the adapter
    if err != nil { return Receipt{}, mapUpstreamError(err) } // local error vocabulary
    return fromLegacy(resp)
}
